CREATE FUNCTION public.is_sales_manager(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN('super_admin','admin','lead_manager')) $$;
CREATE FUNCTION public.can_view_sales(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN('super_admin','admin','lead_manager','viewer')) $$;
CREATE FUNCTION public.is_sales_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN('super_admin','admin','lead_manager','sales_executive','store_manager','funding_manager','global_manager')) $$;
CREATE TABLE public.crm_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 120),company text,designation text,phone text,email text,city text,gstin text,address text,notes text,owner_id uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_contacts TO authenticated; GRANT ALL ON public.crm_contacts TO service_role; ALTER TABLE public.crm_contacts ENABLE ROW LEVEL SECURITY; CREATE POLICY contacts_read ON public.crm_contacts FOR SELECT TO authenticated USING(public.is_sales_staff(auth.uid()) OR public.can_view_sales(auth.uid())); CREATE POLICY contacts_add ON public.crm_contacts FOR INSERT TO authenticated WITH CHECK(public.is_sales_staff(auth.uid()) AND(owner_id=auth.uid() OR public.is_sales_manager(auth.uid()))); CREATE POLICY contacts_edit ON public.crm_contacts FOR UPDATE TO authenticated USING(owner_id=auth.uid() OR public.is_sales_manager(auth.uid())) WITH CHECK(owner_id=auth.uid() OR public.is_sales_manager(auth.uid())); CREATE POLICY contacts_delete ON public.crm_contacts FOR DELETE TO authenticated USING(public.is_sales_manager(auth.uid()));
CREATE TABLE public.crm_deals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 200),company text,contact_name text,phone text,email text,value numeric(14,2) NOT NULL DEFAULT 0 CHECK(value>=0),pipeline text NOT NULL DEFAULT 'general' CHECK(pipeline IN('manufacturer','retailer','distributor','funding','global','general')),stage text NOT NULL DEFAULT 'new' CHECK(stage IN('new','qualified','proposal','negotiation','won','lost')),owner_id uuid NOT NULL DEFAULT auth.uid(),lead_id uuid REFERENCES public.leads(id) ON DELETE SET NULL,expected_close date,notes text,closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),partner_id uuid,contact_id uuid REFERENCES public.crm_contacts(id) ON DELETE SET NULL,next_followup_at timestamptz,followup_note text); GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_deals TO authenticated; GRANT ALL ON public.crm_deals TO service_role; ALTER TABLE public.crm_deals ENABLE ROW LEVEL SECURITY; CREATE POLICY deals_read ON public.crm_deals FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.can_view_sales(auth.uid()) OR(partner_id=auth.uid() AND public.has_role(auth.uid(),'partner'))); CREATE POLICY deals_add ON public.crm_deals FOR INSERT TO authenticated WITH CHECK(public.is_sales_staff(auth.uid()) AND(owner_id=auth.uid() OR public.is_sales_manager(auth.uid()))); CREATE POLICY deals_edit ON public.crm_deals FOR UPDATE TO authenticated USING(owner_id=auth.uid() OR public.is_sales_manager(auth.uid())) WITH CHECK(owner_id=auth.uid() OR public.is_sales_manager(auth.uid())); CREATE POLICY deals_delete ON public.crm_deals FOR DELETE TO authenticated USING(public.is_sales_manager(auth.uid())); CREATE INDEX crm_deals_owner_idx ON public.crm_deals(owner_id); CREATE INDEX crm_deals_followup_idx ON public.crm_deals(next_followup_at) WHERE next_followup_at IS NOT NULL;
CREATE FUNCTION public.can_see_deal(_deal_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.crm_deals d WHERE d.id=_deal_id AND(d.owner_id=auth.uid() OR public.can_view_sales(auth.uid()) OR(d.partner_id=auth.uid() AND public.has_role(auth.uid(),'partner')))) $$;
CREATE FUNCTION public.can_edit_deal(_deal_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.crm_deals d WHERE d.id=_deal_id AND(d.owner_id=auth.uid() OR public.is_sales_manager(auth.uid()))) $$;
CREATE FUNCTION public.crm_deal_touch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at:=now(); IF NEW.stage IN('won','lost') AND(TG_OP='INSERT' OR OLD.stage NOT IN('won','lost')) THEN NEW.closed_at:=now(); ELSIF NEW.stage NOT IN('won','lost') THEN NEW.closed_at:=NULL; END IF; RETURN NEW; END $$; CREATE TRIGGER crm_deals_touch BEFORE INSERT OR UPDATE ON public.crm_deals FOR EACH ROW EXECUTE FUNCTION public.crm_deal_touch();
CREATE TABLE public.crm_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,month date NOT NULL,target_value numeric(14,2) NOT NULL CHECK(target_value>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,month)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_targets TO authenticated; GRANT ALL ON public.crm_targets TO service_role; ALTER TABLE public.crm_targets ENABLE ROW LEVEL SECURITY; CREATE POLICY targets_read ON public.crm_targets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_view_sales(auth.uid())); CREATE POLICY targets_manage ON public.crm_targets FOR ALL TO authenticated USING(public.is_sales_manager(auth.uid())) WITH CHECK(public.is_sales_manager(auth.uid()));
CREATE TABLE public.crm_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),deal_id uuid NOT NULL REFERENCES public.crm_deals(id) ON DELETE CASCADE,name text NOT NULL,file_path text NOT NULL UNIQUE,size_bytes bigint,uploaded_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,DELETE ON public.crm_documents TO authenticated; GRANT ALL ON public.crm_documents TO service_role; ALTER TABLE public.crm_documents ENABLE ROW LEVEL SECURITY; CREATE POLICY documents_read ON public.crm_documents FOR SELECT TO authenticated USING(public.can_see_deal(deal_id)); CREATE POLICY documents_add ON public.crm_documents FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND public.can_edit_deal(deal_id)); CREATE POLICY documents_delete ON public.crm_documents FOR DELETE TO authenticated USING(uploaded_by=auth.uid() OR public.is_sales_manager(auth.uid()));
CREATE TABLE public.crm_deal_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),deal_id uuid NOT NULL REFERENCES public.crm_deals(id) ON DELETE CASCADE,user_id uuid NOT NULL DEFAULT auth.uid(),kind text NOT NULL DEFAULT 'note' CHECK(kind IN('call','meeting','whatsapp','email','note','stage','quote')),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,DELETE ON public.crm_deal_activities TO authenticated; GRANT ALL ON public.crm_deal_activities TO service_role; ALTER TABLE public.crm_deal_activities ENABLE ROW LEVEL SECURITY; CREATE POLICY deal_activities_read ON public.crm_deal_activities FOR SELECT TO authenticated USING(public.can_see_deal(deal_id)); CREATE POLICY deal_activities_add ON public.crm_deal_activities FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.can_edit_deal(deal_id)); CREATE POLICY deal_activities_delete ON public.crm_deal_activities FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.is_sales_manager(auth.uid()));
CREATE TABLE public.crm_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),deal_id uuid NOT NULL REFERENCES public.crm_deals(id) ON DELETE CASCADE,quote_number text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','accepted','rejected')),items jsonb NOT NULL DEFAULT '[]'::jsonb,gst_percent numeric(5,2) NOT NULL DEFAULT 18,notes text,valid_until date,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_quotes TO authenticated; GRANT ALL ON public.crm_quotes TO service_role; ALTER TABLE public.crm_quotes ENABLE ROW LEVEL SECURITY; CREATE POLICY quotes_read ON public.crm_quotes FOR SELECT TO authenticated USING(public.can_see_deal(deal_id)); CREATE POLICY quotes_add ON public.crm_quotes FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.can_edit_deal(deal_id)); CREATE POLICY quotes_edit ON public.crm_quotes FOR UPDATE TO authenticated USING(public.can_edit_deal(deal_id)) WITH CHECK(public.can_edit_deal(deal_id)); CREATE POLICY quotes_delete ON public.crm_quotes FOR DELETE TO authenticated USING(created_by=auth.uid() OR public.is_sales_manager(auth.uid()));
CREATE POLICY crm_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='crm-documents' AND public.can_see_deal(((storage.foldername(name))[1])::uuid)); CREATE POLICY crm_storage_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='crm-documents' AND public.can_edit_deal(((storage.foldername(name))[1])::uuid)); CREATE POLICY crm_storage_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='crm-documents' AND(owner=auth.uid() OR public.is_sales_manager(auth.uid())));